#!/usr/bin/env bash
set -euo pipefail
DRY=${1:-0}
UTM=${2:-0}
HYPR=${XDG_CONFIG_HOME:-$HOME/.config}/hypr
CONFIG=$HYPR/hyprland.lua
[[ -f $CONFIG ]] || { echo 'Merge mode requires an existing Hyprland 0.55+ Lua configuration.' >&2; exit 1; }
if [[ $DRY == 1 ]]; then echo "would add SekaiPop session to $CONFIG (with backup)"; exit 0; fi
# Own only this small file; preserve user-authored versions on subsequent runs.
if [[ ! -e $HYPR/sekaipop_session.lua ]]; then
    cat > "$HYPR/sekaipop_session.lua" <<'LUA'
-- Generated by SekaiPop. Keep other notification/polkit agents disabled in this session.
hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("qs -c sekaipop")
end)
LUA
fi
if [[ $UTM == 1 ]] && ! grep -q 'QSG_RHI_BACKEND' "$HYPR/sekaipop_session.lua"; then
    printf '\nhl.env("QSG_RHI_BACKEND", "opengl")\nhl.on("hyprland.start", function() hl.exec_cmd("spice-vdagent") end)\n' >> "$HYPR/sekaipop_session.lua"
fi
if ! grep -q 'sekaipop_session'  "$CONFIG"; then
    cp -a "$CONFIG" "$CONFIG.sekaipop-backup-$(date +%Y%m%d-%H%M%S)"
    printf '\npcall(require, "sekaipop_session")\n' >> "$CONFIG"
fi
